import six
from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass
from taf.ul.ettf.logger import custom_logger
from taf.ul.ettf.events.comparator import On
from taf.ul.ettf.events.event import Teardown
from taf.ul.ettf.events.lifetime_policy import OneTimeCall
from taf.ul.ettf.events.notifier import Notifier
from taf.ul.ettf.utils.exception import LibraryError
from taf.ul.ettf.utils.robot_handlers import get_callback_name
from taf.ul.ettf.utils.var_manager import VarManager


if six.PY3:
    unicode = str
logger = custom_logger('PolicyScheduler')

IGNORED_POLICY_NAMES = ['false', 'no']


class InvalidValueType(LibraryError):
    def __init__(self, cause, message):
        super(InvalidValueType, self).__init__(cause, message)


class ValueNotCallableError(LibraryError):
    def __init__(self, cause, message):
        super(ValueNotCallableError, self).__init__(cause, message)


class PolicyCallback(object):
    def __init__(self, callback, teardown_callback, trigger_condition=On, trigger_event=Teardown, callback_name=None):
        self._callback = callback
        self._teardown_callback = teardown_callback
        self._trigger_condition = trigger_condition
        self._trigger_event = trigger_event
        self._callback_name = callback_name

    @property
    def __name__(self):
        return self._callback_name or get_callback_name(self._teardown_callback)

    def __call__(self):
        self._register()
        self._callback()

    def _register(self):
        Notifier().register(self._teardown_callback, self._trigger_condition(self._trigger_event), OneTimeCall())


class Policy(dict):
    def __init__(self, *args, **kwargs):
        super(Policy, self).__init__(*args, **kwargs)
        self._check_values_for_callable()

    def _check_values_for_callable(self):
        for list_of_values in self.values():
            if not isinstance(list_of_values, list):
                raise InvalidValueType('Policy values have to be lists. ',
                                       'Invalid: {}'.format(list_of_values))
            for value in list_of_values:
                if not callable(value):
                    raise ValueNotCallableError('Singular values have to be callable. ',
                                                'Invalid: {}'.format(value))


class PolicyScheduler(with_metaclass(ABCMeta)):
    def get(self):
        variable_value = self._get_robot_variable(self._policy_name())
        if self._has_expected_type(variable_value):
            return variable_value

        if variable_value and isinstance(variable_value, (str, unicode)):
            variable_value = self._get_policy_based_on_name(variable_value)
            if variable_value:
                return variable_value

        return self._default_value()

    def _get_robot_variable(self, var_name):
        return VarManager(var_name, default_var_value='').get_variable()

    def _get_policy_based_on_name(self, variable_name):
        variable_value = self._get_robot_variable(variable_name)
        if variable_name and not self._has_expected_type(variable_value):
            if self._should_be_ignored(variable_value):
                return
            self._print_warning(variable_name)
            return
        return variable_value

    def _should_be_ignored(self, variable_value):
        return str(variable_value).lower() in IGNORED_POLICY_NAMES

    def _print_warning(self, variable_name):
        logger.warn('Failed to load {} based on name: {}'.format(self._policy_name(), variable_name))
        logger.warn('Default policy will be used')

    def _has_expected_type(self, value):
        return isinstance(value, Policy)

    @abstractmethod
    def _policy_name(self):
        raise NotImplementedError

    @abstractmethod
    def _default_value(self):
        raise NotImplementedError
